  AwakerPotency_131875_PotencyDesc = {
    Text = "โล่พื้นฐานจากระเบิดพลังอาลีมัสของซายะเพิ่มขึ้น 5%, การกัดกร่อนพื้นฐานที่「บุปผาเลือดเนื้อผลิบาน」ก่อให้เกิดเพิ่มขึ้น 10%. ทุกๆ 1% ของคุณสมบัติอัตราดรอปผนึกขี้ผึ้งสีนิลที่ซายะเอง, วงล้อมชีวิต และพันธสัญญาที่ติดตั้งให้มา, โล่พื้นฐานจากระเบิดพลังอาลีมัสของซายะจะเพิ่มขึ้น 0.25%, และการกัดกร่อนพื้นฐานที่「บุปผาเลือดเนื้อผลิบาน」ก่อให้เกิดจะเพิ่มขึ้นเพิ่มเติม 0.5%."
