  AwakerPotency_13227_PotencyDesc = {
    Text = "「พรแด่เถ้ากระดูกและโลหิต」การหลอมรวมตัวอ่อน +15 ปริมาณการฟื้นฟูเตาหลอมเลือดที่สะสมจะเพิ่มขึ้นตามจำนวนรอบ โดยจะเพิ่มขึ้นเท่ากับค่าร่างกาย [Arg1]%(จะเพิ่มขึ้นตามระดับของ「พรแด่เถ้ากระดูกและโลหิต」)；「ทุกข์ที่ควรถูกชำระ」อัตราคริติคอลเพิ่มขึ้น 25% และได้รับ「เตรียมพร้อม1」."
