  AwakerPotency_145374_PotencyDesc = {
    Text = "โบนัสความเสียหายที่ 「คมดาบสะบั้นมิติ」 ได้รับจาก 「ดาบยักษ์: วาฬร่วงหล่น」 จะเพิ่มเป็นสองเท่า. การ 「ประลองมรณะ」 ครั้งแรกของแต่ละรอบจะไม่บริโภคอริธเมทิกา."
