  AwakerPotency_148465_PotencyDesc = {
    Text = "อัตราส่วนโล่และพลังที่「อัศวินหัวใจไม่ดับสูญ」สร้างเพิ่มขึ้น 20%, แต่ละชั้น「คลื่นใต้น้ำ」ทำให้ดาเมจคริติคอลของนิกายสาบาน·โอเกียร์เพิ่มขึ้น 10%.\nสำหรับทุก 1% อัตราคริติคอลของผู้ปลุกตื่นนิกายสาบาน·โอเกียร์เอง, วงล้อมชีวิต, พันธสัญญา, อัตราส่วนโล่และพลังที่「อัศวินหัวใจไม่ดับสูญ」สร้างจะเพิ่มขึ้นเพิ่มเติมอีก 0.6%, แต่ละชั้น「คลื่นใต้น้ำ」ทำให้ดาเมจคริติคอลของนิกายสาบาน·โอเกียร์เพิ่มขึ้นเพิ่มเติมอีก 0.3%."
  },
