    Text = "「เจ็ดศิลป์ สรรค์คุณธรรม」โล่และพละกำลังชั่วคราวที่ได้รับเพิ่มขึ้น 20%,      หากอยู่ในสถานะแตกหัก,     「เจ็ดศิลป์ สรรค์คุณธรรม」จะได้รับโล่เพิ่มเติม 33%."
