  AwakerPotency_78946_PotencyDesc = {
    Text = "「สัญญาณธงไร้ระเบียบ」ทำให้ศัตรูทั้งหมดอ่อนแอ 1 รอบ ทุกครั้งที่มีหนวดสัมผัส 1 เส้น ความสามารถนำร่อง โล่ พละกำลัง และความเสียหายจากหนวดสัมผัสจะเพิ่มขึ้น 5% สูงสุด 50%。"
