  },
  AwakerPotency_79045_PotencyName = {
    Text = "รู้ทุกสิ่งและสามารถทำได้ทุกอย่าง"
  },
  AwakerPotency_79046_PotencyDesc = {
    Text = "「การโจมตีพื้นฐาน」และ「การป้องกันพื้นฐาน」ทำให้ฟาโรห์ดำได้รับอัตราคริติคอล 3% และดาเมจคริติคอลสูงสุด 30% เมื่อเริ่มการสำรวจและเกิดการต่อต้านความตายเป็นครั้งแรก จะได้รับการ์ด「เสียงสะท้อนจากอดีตกาล」หนึ่งใบในมือ。"
