    Text = "「บำบัดสร้างสิ่งใหม่」จะได้รับพลังงานกุญแจเงินของคลีเมนไทน์เพิ่มขึ้น 200％ สำหรับการชาร์จกุญแจเงิน ทุกครั้งที่ลบ 1 ชั้นของ「ความรู้สึกเห็นใจ」จะทำให้ความเสียหายพื้นฐานที่คลีเมนไทน์ทำได้เพิ่มขึ้น 3％ หลังจากจบการต่อสู้แต่ละครั้ง จะทำให้ความเสียหายพื้นฐานที่คลีเมนไทน์ทำได้เพิ่มขึ้น 25％。"
  },
  AwakerPotency_79132_PotencyName = {
    Text = "การเดินทางเพื่อเยียวยาจิตวิญญาณ"
  },
  AwakerPotency_79133_PotencyDesc = {
    Text = "เมื่อสิ้นสุดเทิร์นจะได้รับ 2 ชั้นของ「ความรู้สึกเห็นใจ」. ขีดจำกัดของการสะสมชั้นของ「ความรู้สึกเห็นใจ」,「ความเสียหายทางจิตใจ」,「การยึดติดด้วยความกลัว」จะเพิ่มขึ้นเป็น 15.。"
  },
  AwakerPotency_79133_PotencyName = {
    Text = "คุณจะหายเป็นปกติในที่สุด"
  },
  AwakerPotency_79134_PotencyName = {
    Text = "การพัฒนาบุคลิกภาพ"
  },
  AwakerPotency_79135_PotencyName = {
    Text = "การพัฒนาบุคลิกภาพ"
  },
  AwakerPotency_79136_PotencyName = {
    Text = "การพัฒนาบุคลิกภาพ"
  },
  AwakerPotency_79137_PotencyDesc = {
    Text = "「การโจมตีพื้นฐาน」และ「การป้องกันพื้นฐาน」ทำให้อาฟโกร์มงได้รับอัตราคริติคอล 3% และดาเมจคริติคอล สูงสุด 30% เมื่อเริ่มสำรวจครั้งแรกที่กระตุ้นการต่อต้านความตาย จะได้รับการ์ด「เสียงสะท้อนจากอดีตกาล」หนึ่งใบในมือ。"
  },
  AwakerPotency_79137_PotencyName = {
