  },
  AwakerPotency_79141_PotencyDesc = {
    Text = "<OverLimitUtlSkillKeywords:การระเบิดเกินขีดจำกัด>：อาฟโกร์มงทำให้ความเสียหาย,      โล่,      และการฟื้นฟู HP เพิ่มขึ้นชั่วคราว 35%.เปลี่ยนเป็นค้นพบ 3 ใบจากการ์ดทักษะในดินแดนปัจจุบัน 10 ใบ และได้รับ 3 อริธเมทิกาในทันที."
  },
  AwakerPotency_79141_PotencyName = {
    Text = "ความสว่างไม่รู้จบของพันล้าน"
