  AwakerPotency_79142_PotencyName = {
    Text = "การพัฒนาบุคลิกภาพ"
  },
  AwakerPotency_79143_PotencyDesc = {
    Text = "วิญญาณตื่นรู้「ผลไม้หวานแสนเย้ายวน」ได้รับการเสริมสร้าง, หลังจากใช้เตาหลอมเลือด ทำให้การค้นพบ「ปาฏิหาริย์ประทานพร」ครั้งถัดไปมี「พร」เพิ่มเติม 1 ใบต่อชุด. หลังจากเล่น「พร」, หลอมรวมตัวอ่อน +10, ยิ่ง HP ปัจจุบันต่ำยิ่งมีผลมากขึ้น, เพิ่มได้สูงสุด 100%."
  },
  AwakerPotency_79143_PotencyName = {
    Text = "จันทร์เสี้ยวลอยเด่นกลางฟากฟ้า"
  },
  AwakerPotency_79144_PotencyName = {
    Text = "การพัฒนาบุคลิกภาพ"
  },
  AwakerPotency_79145_PotencyName = {
    Text = "การพัฒนาบุคลิกภาพ"
