  AwakerPotency_79151_PotencyDesc = {
    Text = "เมื่อ「จิตศักดิ์สิทธิ์」ถูกใช้จนหมดจากการเล่นครั้งที่ 3 จะทำให้การ์ดคำสั่งใบถัดไปของตัวเองมีผลเพิ่มอีก 1 ครั้ง."
